/**
 * Founder-approved episode backfill (2026-10-30): appends the canonical
 * per-turn rows listed in RECEIPT_PATH to their episode row, oldest first,
 * then makes the episode's embeddings current.
 *
 * Inert until a receipt generated by
 * server/scripts/generate-episode-backfill-receipt.ts is committed and
 * approved.
 *
 * One transaction for the whole batch (server/services/episode-backfill.ts
 * planBackfill decides it):
 *   - the episode row is locked FOR UPDATE until commit, so every other
 *     episode writer (`content || ...`) waits and lands after the backfill;
 *   - each listed source row is locked FOR SHARE and must still match its
 *     entry: content hash, capture id, created_at and canonical membership;
 *   - the receipt must fill an appendable tail: no canonical turn newer than
 *     the oldest missing one (by created_at, then id) may already be in the
 *     episode;
 *   - all missing turns are appended in one UPDATE, or nothing is.
 * Already-present turns are skipped, so a re-run after success writes nothing.
 * A refusal is reported (never forced) and does not fail the deploy.
 *
 * Embeddings: the projection append path never re-embeds. After a complete
 * backfill the expected embedding arms (whole memory, summary, every chunk;
 * the same texts reembedConversationMemory hashes) are compared with what is
 * stored. Outcomes: already current; updated (re-embed ran AND the check then
 * passes); blocked (no embedding configuration, nothing called); failed (the
 * call threw, or it resolved but the check still fails). A resolved call alone
 * never counts as success. Not current is retried on the next deploy.
 */
import { existsSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import type { Pool } from '@neondatabase/serverless';
import type { DataOpResult } from '../run-data-ops';
import {
  CREATED_AT_SQL, PER_TURN_ARC, PER_TURN_TAG, embeddingCoverage, episodeBackfillReceiptProblem, planBackfill,
  type EpisodeBackfillReceipt, type ExpectedArm, type SourceRow, type StoredArm,
} from '../../server/services/episode-backfill';

export const RECEIPT_PATH = join(dirname(fileURLToPath(import.meta.url)), 'backfill-episode-turns.receipt.json');

/** The connection surface the backfill needs; a real Pool provides it. */
export interface BackfillPool {
  connect(): Promise<{ query(sql: string, params?: unknown[]): Promise<{ rows: any[] }>; release(): void }>;
  query(sql: string, params?: unknown[]): Promise<{ rows: any[] }>;
}

export type BackfillOutcome =
  | { status: 'appended'; appended: number; alreadyPresent: number }
  | { status: 'complete'; alreadyPresent: number }
  | { status: 'refused'; reason: string; rowId?: string };

const SOURCE_COLUMNS = `id, content, ${CREATED_AT_SQL} AS created_at, arc_name, tags`;
const toSource = (r: any): SourceRow => ({ id: r.id, content: r.content, createdAt: r.created_at, arcName: r.arc_name, tags: r.tags });

/** Apply one approved receipt in a single transaction. Exported so its rules are tested with real and fake pools. */
export async function applyBackfill(pool: BackfillPool, receipt: EpisodeBackfillReceipt): Promise<BackfillOutcome> {
  const problem = episodeBackfillReceiptProblem(receipt);
  if (problem) throw new Error(`episode backfill receipt refused: ${problem}`);
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const episode = (await client.query(
      'SELECT title, content FROM conversation_memories WHERE id = $1 FOR UPDATE', [receipt.episodeId],
    )).rows[0];
    let outcome: BackfillOutcome;
    if (!episode || typeof episode.content !== 'string') {
      outcome = { status: 'refused', reason: 'episode row missing' };
    } else if (episode.title !== receipt.episodeTitle) {
      outcome = { status: 'refused', reason: 'episode title differs from the receipt' };
    } else {
      const ids = receipt.entries.map((e) => e.rowId);
      const sources = new Map((await client.query(
        `SELECT ${SOURCE_COLUMNS} FROM conversation_memories WHERE id = ANY($1::varchar[]) FOR SHARE`, [ids],
      )).rows.map((r) => [r.id as string, toSource(r)]));
      const newer = (await client.query(
        `SELECT ${SOURCE_COLUMNS} FROM conversation_memories
          WHERE arc_name = $1 AND $2 = ANY(tags) AND ${CREATED_AT_SQL} >= $3`,
        [PER_TURN_ARC, PER_TURN_TAG, receipt.entries[0].createdAt],
      )).rows.map(toSource);
      const plan = planBackfill(receipt, sources, newer, episode.content);
      if (plan.status === 'append') {
        await client.query('UPDATE conversation_memories SET content = content || $2 WHERE id = $1', [receipt.episodeId, plan.text]);
        outcome = { status: 'appended', appended: plan.appending, alreadyPresent: plan.alreadyPresent };
      } else if (plan.status === 'complete') {
        outcome = { status: 'complete', alreadyPresent: plan.alreadyPresent };
      } else {
        outcome = plan;
      }
    }
    await client.query(outcome.status === 'appended' ? 'COMMIT' : 'ROLLBACK');
    return outcome;
  } catch (e) {
    await client.query('ROLLBACK').catch(() => undefined);
    throw e;
  } finally {
    client.release();
  }
}

/** What the embedding step needs; production wires the real helpers, tests inject fakes. */
export interface EmbeddingDeps {
  configured(): boolean;
  expected(episode: { id: string; title: string | null; summary: string | null; content: string }): Promise<ExpectedArm[]>;
  stored(episodeId: string): Promise<StoredArm[]>;
  reembed(episodeId: string): Promise<void>;
}

/** Make the episode's embeddings current and say exactly what happened. */
export async function ensureEmbeddings(pool: BackfillPool, episodeId: string, deps: EmbeddingDeps): Promise<string> {
  const row = (await pool.query('SELECT id, title, summary, content FROM conversation_memories WHERE id = $1', [episodeId])).rows[0];
  if (!row) return 'failed: episode row missing';
  const check = async () => embeddingCoverage(await deps.expected(row), await deps.stored(episodeId), `${episodeId}:chunk:`);
  const before = await check();
  if (before.current) return 'already current';
  if (!deps.configured()) {
    return `blocked: no embedding configuration (missing ${before.missing}, stale ${before.stale}, extra ${before.extra}); not attempted`;
  }
  try {
    await deps.reembed(episodeId);
  } catch (e: any) {
    return `failed: re-embed threw: ${e?.message ?? e}`;
  }
  const after = await check();
  return after.current
    ? 'updated (verified current)'
    : `failed: re-embed resolved but embeddings are not current (missing ${after.missing}, stale ${after.stale}, extra ${after.extra})`;
}

export function describe(outcome: BackfillOutcome, total: number, embeddings: string): string {
  const head = outcome.status === 'appended'
    ? `appended ${outcome.appended}, already present ${outcome.alreadyPresent} of ${total}`
    : outcome.status === 'complete'
      ? `nothing to append, all ${total} present`
      : `REFUSED, nothing written: ${outcome.reason}${outcome.rowId ? ` (${outcome.rowId})` : ''}`;
  return `episode backfill: ${head}; embeddings: ${embeddings}`;
}

/** The data-op body with its embedding dependencies injected. */
export async function runBackfill(pool: BackfillPool, receipt: EpisodeBackfillReceipt, deps: EmbeddingDeps): Promise<DataOpResult> {
  const outcome = await applyBackfill(pool, receipt);
  const embeddings = outcome.status === 'refused'
    ? 'not checked (backfill refused)'
    : await ensureEmbeddings(pool, receipt.episodeId, deps);
  return { applied: outcome.status === 'appended', detail: describe(outcome, receipt.entries.length, embeddings) };
}

async function productionDeps(pool: BackfillPool): Promise<EmbeddingDeps> {
  // server/ modules open their own DB pool on import, so they load only here.
  const { splitIntoChunks, reformatSpeakerHeaders } = await import('../../server/services/memory-embedding-indexer');
  const { hashContent } = await import('../../server/services/semantic-memory-service');
  const { reembedConversationMemory } = await import('../../server/scripts/reembed-memory');
  return {
    configured: () => Boolean(process.env.USER_OPENAI_API_KEY),
    // The exact texts reembedConversationMemory embeds for a global (non-founder) memory.
    async expected(row) {
      const arms: ExpectedArm[] = [{
        memoryType: 'conversation_memory', memoryId: row.id,
        contentHash: hashContent([row.title, row.summary, row.content].filter(Boolean).join('\n\n')),
      }];
      if (row.summary && row.summary.length > 10) {
        arms.push({ memoryType: 'conversation_summary', memoryId: row.id, contentHash: hashContent([row.title, row.summary].filter(Boolean).join('\n\n')) });
      }
      const chunks = splitIntoChunks(row.content);
      chunks.forEach((chunk, i) => arms.push({
        memoryType: 'conversation_chunk', memoryId: `${row.id}:chunk:${i}`,
        contentHash: hashContent(`[Memory: ${row.title ?? 'Untitled'} | Part ${i + 1} of ${chunks.length}]\n\n${reformatSpeakerHeaders(chunk)}`),
      }));
      return arms;
    },
    async stored(episodeId) {
      return (await pool.query(
        `SELECT memory_type, memory_id, content_hash FROM memory_embeddings
          WHERE (memory_type IN ('conversation_memory', 'conversation_summary') AND memory_id = $1)
             OR (memory_type = 'conversation_chunk' AND memory_id LIKE $2)`,
        [episodeId, `${episodeId}:chunk:%`],
      )).rows.map((r) => ({ memoryType: r.memory_type, memoryId: r.memory_id, contentHash: r.content_hash }));
    },
    reembed: (episodeId) => reembedConversationMemory(episodeId),
  };
}

export async function run(pool: Pool): Promise<DataOpResult> {
  if (!existsSync(RECEIPT_PATH)) return { applied: false, detail: 'no approved episode backfill receipt; nothing to do' };
  const receipt = JSON.parse(readFileSync(RECEIPT_PATH, 'utf8')) as EpisodeBackfillReceipt;
  const p = pool as unknown as BackfillPool;
  try {
    return await runBackfill(p, receipt, await productionDeps(p));
  } finally {
    // server/db opened its own pool on import; close it so the pre-deploy
    // process exits promptly instead of waiting on idle connections.
    const { closeDbConnections } = await import('../../server/db');
    await closeDbConnections().catch(() => undefined);
  }
}
